import java.io.*;

public class TestPhase1 {
    public static void main(String[] args) {
        System.out.println("=== Starting Phase 1 Verification Test ===");
        try {
            // 1. Create a ResourceManager
            ResourceManager rm = new ResourceManager("TestRM");

            // 2. Test generic dispatch for addFlight
            System.out.print("Testing addFlight(123, 50, 200)... ");
            TCPMessage msgAddFlight = new TCPMessage("addFlight", 123, 50, 200);
            Object res1 = GenericDispatcher.dispatch(rm, msgAddFlight);
            if (Boolean.TRUE.equals(res1)) {
                System.out.println("PASSED (Result: " + res1 + ")");
            } else {
                System.out.println("FAILED (Result: " + res1 + ")");
            }

            // 3. Test generic dispatch for queryFlight
            System.out.print("Testing queryFlight(123)... ");
            TCPMessage msgQueryFlight = new TCPMessage("queryFlight", 123);
            Object res2 = GenericDispatcher.dispatch(rm, msgQueryFlight);
            if (Integer.valueOf(50).equals(res2)) {
                System.out.println("PASSED (Seats available: " + res2 + ")");
            } else {
                System.out.println("FAILED (Seats available: " + res2 + ")");
            }

            // 4. Test generic dispatch for queryFlightPrice
            System.out.print("Testing queryFlightPrice(123)... ");
            TCPMessage msgQueryPrice = new TCPMessage("queryFlightPrice", 123);
            Object res3 = GenericDispatcher.dispatch(rm, msgQueryPrice);
            if (Integer.valueOf(200).equals(res3)) {
                System.out.println("PASSED (Price: " + res3 + ")");
            } else {
                System.out.println("FAILED (Price: " + res3 + ")");
            }

            // 5. Test generic dispatch for addCars (String, int, int)
            System.out.print("Testing addCars(\"Montreal\", 10, 50)... ");
            TCPMessage msgAddCars = new TCPMessage("addCars", "Montreal", 10, 50);
            Object res4 = GenericDispatcher.dispatch(rm, msgAddCars);
            if (Boolean.TRUE.equals(res4)) {
                System.out.println("PASSED (Result: " + res4 + ")");
            } else {
                System.out.println("FAILED (Result: " + res4 + ")");
            }

            // 6. Test Serialization / Deserialization (simulating TCP network transfer)
            System.out.print("Testing TCPMessage serialization / deserialization... ");
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(msgAddFlight);
            oos.flush();

            ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
            ObjectInputStream ois = new ObjectInputStream(bais);
            TCPMessage deserializedMsg = (TCPMessage) ois.readObject();

            if (deserializedMsg.getMethodName().equals("addFlight") &&
                deserializedMsg.getArgs().length == 3 &&
                Integer.valueOf(123).equals(deserializedMsg.getArgs()[0])) {
                System.out.println("PASSED (Serialized & Deserialized successfully)");
            } else {
                System.out.println("FAILED");
            }

            // 7. Test NoSuchMethodException handling
            System.out.print("Testing invalid method call handling... ");
            try {
                TCPMessage badMsg = new TCPMessage("nonExistentMethod", 123);
                GenericDispatcher.dispatch(rm, badMsg);
                System.out.println("FAILED (Should have thrown NoSuchMethodException)");
            } catch (NoSuchMethodException e) {
                System.out.println("PASSED (Caught expected NoSuchMethodException: " + e.getMessage() + ")");
            }

            System.out.println("\n>>> ALL PHASE 1 CHECKS PASSED SUCCESSFULLY! <<<");

        } catch (Exception e) {
            System.err.println("Test encountered an unexpected error:");
            e.printStackTrace();
        }
    }
}

