package Server.TCP;

import Server.Interface.IResourceManagerInternal;
import Server.Interface.TCPMessage;

import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.net.Socket;
import java.rmi.RemoteException;
import java.util.Vector;

public class TCPResourceManagerProxy implements IResourceManagerInternal {
    private Socket m_socket;
    private ObjectOutputStream m_out;
    private ObjectInputStream m_in;

    public TCPResourceManagerProxy(String host, int port) throws IOException {
        this.m_socket = new Socket(host, port);
        this.m_out = new ObjectOutputStream(m_socket.getOutputStream());
        this.m_out.flush();
        this.m_in = new ObjectInputStream(m_socket.getInputStream());
    }

    /**
     * General wrapping / message creation service.
     * All operations delegate to this method.
     */
    private synchronized Object sendRequest(String methodName, Object... args) throws RemoteException {
        try {
            TCPMessage request = new TCPMessage(methodName, args);
            m_out.writeObject(request);
            m_out.flush();

            TCPMessage response = (TCPMessage) m_in.readObject();
            if (response.getException() != null) {
                if (response.getException() instanceof RemoteException) {
                    throw (RemoteException) response.getException();
                }
                throw new RemoteException("Server error: " + response.getException().getMessage(), response.getException());
            }
            return response.getResult();
        } catch (RemoteException re) {
            throw re;
        } catch (Exception e) {
            throw new RemoteException("TCP communication error: " + e.getMessage(), e);
        }
    }

    // --- IResourceManager Methods ---

    public boolean addFlight(int flightNum, int flightSeats, int flightPrice) throws RemoteException {
        return (Boolean) sendRequest("addFlight", flightNum, flightSeats, flightPrice);
    }

    public boolean addCars(String location, int numCars, int price) throws RemoteException {
        return (Boolean) sendRequest("addCars", location, numCars, price);
    }

    public boolean addRooms(String location, int numRooms, int price) throws RemoteException {
        return (Boolean) sendRequest("addRooms", location, numRooms, price);
    }

    public int newCustomer() throws RemoteException {
        return (Integer) sendRequest("newCustomer");
    }

    public boolean newCustomer(int cid) throws RemoteException {
        return (Boolean) sendRequest("newCustomer", cid);
    }

    public boolean deleteFlight(int flightNum) throws RemoteException {
        return (Boolean) sendRequest("deleteFlight", flightNum);
    }

    public boolean deleteCars(String location) throws RemoteException {
        return (Boolean) sendRequest("deleteCars", location);
    }

    public boolean deleteRooms(String location) throws RemoteException {
        return (Boolean) sendRequest("deleteRooms", location);
    }

    public boolean deleteCustomer(int customerID) throws RemoteException {
        return (Boolean) sendRequest("deleteCustomer", customerID);
    }

    public int queryFlight(int flightNumber) throws RemoteException {
        return (Integer) sendRequest("queryFlight", flightNumber);
    }

    public int queryCars(String location) throws RemoteException {
        return (Integer) sendRequest("queryCars", location);
    }

    public int queryRooms(String location) throws RemoteException {
        return (Integer) sendRequest("queryRooms", location);
    }

    public String queryCustomerInfo(int customerID) throws RemoteException {
        return (String) sendRequest("queryCustomerInfo", customerID);
    }

    public int queryFlightPrice(int flightNumber) throws RemoteException {
        return (Integer) sendRequest("queryFlightPrice", flightNumber);
    }

    public int queryCarsPrice(String location) throws RemoteException {
        return (Integer) sendRequest("queryCarsPrice", location);
    }

    public int queryRoomsPrice(String location) throws RemoteException {
        return (Integer) sendRequest("queryRoomsPrice", location);
    }

    public boolean reserveFlight(int customerID, int flightNumber) throws RemoteException {
        return (Boolean) sendRequest("reserveFlight", customerID, flightNumber);
    }

    public boolean reserveCar(int customerID, String location) throws RemoteException {
        return (Boolean) sendRequest("reserveCar", customerID, location);
    }

    public boolean reserveRoom(int customerID, String location) throws RemoteException {
        return (Boolean) sendRequest("reserveRoom", customerID, location);
    }

    public boolean bundle(int customerID, Vector<String> flightNumbers, String location, boolean car, boolean room) throws RemoteException {
        return (Boolean) sendRequest("bundle", customerID, flightNumbers, location, car, room);
    }

    public String getName() throws RemoteException {
        return (String) sendRequest("getName");
    }

    // --- IResourceManagerInternal Methods ---

    public int reserveResource(String key) throws RemoteException {
        return (Integer) sendRequest("reserveResource", key);
    }

    public boolean unreserveResource(String key, int count) throws RemoteException {
        return (Boolean) sendRequest("unreserveResource", key, count);
    }

    public boolean isClosed() {
        return m_socket == null || m_socket.isClosed();
    }

    public void close() {
        try {
            if (m_socket != null) m_socket.close();
        } catch (IOException ignored) {}
    }
}

package Server.TCP;

import Server.Interface.IResourceManagerInternal;

import java.io.IOException;
import java.rmi.RemoteException;
import java.util.Vector;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

/**
 * Thread-safe connection pool for communicating with a backend ResourceManager.
 * Allows multiple concurrent client handler threads in the Middleware to make calls
 * to the same backend RM without blocking one another.
 */
public class RMConnectionPool implements IResourceManagerInternal {
    private final String m_host;
    private final int m_port;
    private final BlockingQueue<TCPResourceManagerProxy> m_pool = new LinkedBlockingQueue<TCPResourceManagerProxy>();

    public RMConnectionPool(String host, int port) {
        this.m_host = host;
        this.m_port = port;
    }

    private TCPResourceManagerProxy acquire() throws RemoteException {
        TCPResourceManagerProxy proxy = m_pool.poll();
        if (proxy == null || proxy.isClosed()) {
            try {
                proxy = new TCPResourceManagerProxy(m_host, m_port);
            } catch (IOException e) {
                throw new RemoteException("Failed to connect to RM at " + m_host + ":" + m_port + ": " + e.getMessage(), e);
            }
        }
        return proxy;
    }

    private void release(TCPResourceManagerProxy proxy) {
        if (proxy != null && !proxy.isClosed()) {
            m_pool.offer(proxy);
        }
    }

    // Functional interface for executing a remote call with automatic proxy acquisition and release
    @FunctionalInterface
    private interface RMCall<T> {
        T call(TCPResourceManagerProxy proxy) throws RemoteException;
    }

    private <T> T execute(RMCall<T> action) throws RemoteException {
        TCPResourceManagerProxy proxy = acquire();
        try {
            return action.call(proxy);
        } catch (RemoteException e) {
            proxy.close();
            throw e;
        } finally {
            release(proxy);
        }
    }

    public boolean addFlight(int flightNum, int flightSeats, int flightPrice) throws RemoteException {
        return execute(p -> p.addFlight(flightNum, flightSeats, flightPrice));
    }

    public boolean addCars(String location, int count, int price) throws RemoteException {
        return execute(p -> p.addCars(location, count, price));
    }

    public boolean addRooms(String location, int count, int price) throws RemoteException {
        return execute(p -> p.addRooms(location, count, price));
    }

    public int newCustomer() throws RemoteException {
        return execute(p -> p.newCustomer());
    }

    public boolean newCustomer(int cid) throws RemoteException {
        return execute(p -> p.newCustomer(cid));
    }

    public boolean deleteFlight(int flightNum) throws RemoteException {
        return execute(p -> p.deleteFlight(flightNum));
    }

    public boolean deleteCars(String location) throws RemoteException {
        return execute(p -> p.deleteCars(location));
    }

    public boolean deleteRooms(String location) throws RemoteException {
        return execute(p -> p.deleteRooms(location));
    }

    public boolean deleteCustomer(int customerID) throws RemoteException {
        return execute(p -> p.deleteCustomer(customerID));
    }

    public int queryFlight(int flightNum) throws RemoteException {
        return execute(p -> p.queryFlight(flightNum));
    }

    public int queryCars(String location) throws RemoteException {
        return execute(p -> p.queryCars(location));
    }

    public int queryRooms(String location) throws RemoteException {
        return execute(p -> p.queryRooms(location));
    }

    public String queryCustomerInfo(int customerID) throws RemoteException {
        return execute(p -> p.queryCustomerInfo(customerID));
    }

    public int queryFlightPrice(int flightNum) throws RemoteException {
        return execute(p -> p.queryFlightPrice(flightNum));
    }

    public int queryCarsPrice(String location) throws RemoteException {
        return execute(p -> p.queryCarsPrice(location));
    }

    public int queryRoomsPrice(String location) throws RemoteException {
        return execute(p -> p.queryRoomsPrice(location));
    }

    public boolean reserveFlight(int customerID, int flightNum) throws RemoteException {
        return execute(p -> p.reserveFlight(customerID, flightNum));
    }

    public boolean reserveCar(int customerID, String location) throws RemoteException {
        return execute(p -> p.reserveCar(customerID, location));
    }

    public boolean reserveRoom(int customerID, String location) throws RemoteException {
        return execute(p -> p.reserveRoom(customerID, location));
    }

    public boolean bundle(int customerId, Vector<String> flightNumbers, String location, boolean car, boolean room) throws RemoteException {
        return execute(p -> p.bundle(customerId, flightNumbers, location, car, room));
    }

    public String getName() throws RemoteException {
        return execute(p -> p.getName());
    }

    public int reserveResource(String key) throws RemoteException {
        return execute(p -> p.reserveResource(key));
    }

    public boolean unreserveResource(String key, int count) throws RemoteException {
        return execute(p -> p.unreserveResource(key, count));
    }
}

package Server.TCP;

import Server.Common.*;
import Server.Interface.IResourceManagerInternal;
import Server.Interface.TCPMessage;

import java.io.EOFException;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.SocketException;
import java.rmi.RemoteException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * TCP Middleware for the Travel Reservation System.
 * Sits between clients and the Flights, Cars, and Rooms ResourceManagers.
 *
 * Concurrency & Non-blocking Design:
 * - Listens for incoming client connections and offloads each connection to a thread pool.
 * - Uses thread-safe connection pools to the backend RMs, ensuring that while the Middleware
 *   is waiting for an RM to respond, it continues accepting and processing other client requests.
 * - Customer state is maintained locally in the Middleware.
 * - Per-customer locks allow different customers to perform operations in parallel.
 */
public class TCPMiddleware extends ResourceManager {
    private static String s_serverName = "TCPMiddleware";
    private static int s_middlewarePort = 50000;

    private static String s_flightsHost = "localhost";
    private static int s_flightsPort = 50001;

    private static String s_carsHost = "localhost";
    private static int s_carsPort = 50002;

    private static String s_roomsHost = "localhost";
    private static int s_roomsPort = 50003;

    private IResourceManagerInternal m_flightsRM;
    private IResourceManagerInternal m_carsRM;
    private IResourceManagerInternal m_roomsRM;

    private final ConcurrentHashMap<Integer, Object> m_customerLocks = new ConcurrentHashMap<Integer, Object>();
    private final ExecutorService m_clientThreadPool = Executors.newCachedThreadPool();

    public static void main(String[] args) {
        // Parse arguments: <flightsHost[:port]> <carsHost[:port]> <roomsHost[:port]> [middlewarePort]
        if (args.length >= 3) {
            parseHostPort(args[0], host -> s_flightsHost = host, port -> s_flightsPort = port);
            parseHostPort(args[1], host -> s_carsHost = host, port -> s_carsPort = port);
            parseHostPort(args[2], host -> s_roomsHost = host, port -> s_roomsPort = port);
        }
        if (args.length >= 4) {
            try {
                s_middlewarePort = Integer.parseInt(args[3]);
            } catch (NumberFormatException e) {
                System.err.println("Invalid middleware port: " + args[3]);
                System.exit(1);
            }
        }

        TCPMiddleware middleware = new TCPMiddleware(s_serverName);
        middleware.initConnections();
        middleware.start();
    }

    private interface Setter<T> { void set(T val); }
    private static void parseHostPort(String input, Setter<String> hostSetter, Setter<Integer> portSetter) {
        String[] parts = input.split(":");
        hostSetter.set(parts[0]);
        if (parts.length > 1) {
            try {
                portSetter.set(Integer.parseInt(parts[1]));
            } catch (NumberFormatException ignored) {}
        }
    }

    public TCPMiddleware(String name) {
        super(name);
    }

    public void initConnections() {
        System.out.println("Connecting to Flights RM at " + s_flightsHost + ":" + s_flightsPort);
        this.m_flightsRM = new RMConnectionPool(s_flightsHost, s_flightsPort);

        System.out.println("Connecting to Cars RM at " + s_carsHost + ":" + s_carsPort);
        this.m_carsRM = new RMConnectionPool(s_carsHost, s_carsPort);

        System.out.println("Connecting to Rooms RM at " + s_roomsHost + ":" + s_roomsPort);
        this.m_roomsRM = new RMConnectionPool(s_roomsHost, s_roomsPort);
    }

    public void start() {
        System.out.println("Starting TCP Middleware on port " + s_middlewarePort);

        try (ServerSocket serverSocket = new ServerSocket(s_middlewarePort)) {
            while (true) {
                // Non-blocking accept loop: immediately delegates client socket to a thread pool worker
                Socket clientSocket = serverSocket.accept();
                m_clientThreadPool.execute(() -> handleClient(clientSocket));
            }
        } catch (IOException e) {
            System.err.println("Middleware ServerSocket error: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void handleClient(Socket socket) {
        try {
            ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
            out.flush();
            ObjectInputStream in = new ObjectInputStream(socket.getInputStream());

            while (true) {
                TCPMessage request = (TCPMessage) in.readObject();
                if (request == null) break;

                Object result = null;
                Exception exception = null;
                try {
                    // Uses GenericDispatcher to execute the method on this Middleware instance
                    result = GenericDispatcher.dispatch(this, request);
                } catch (Exception e) {
                    exception = e;
                }

                TCPMessage response = new TCPMessage(request.getId(), result, exception);
                out.writeObject(response);
                out.flush();
            }
        } catch (EOFException | SocketException ignored) {
            // Client disconnected normally
        } catch (Exception e) {
            Trace.warn("Connection error in TCPMiddleware: " + e.getMessage());
        } finally {
            try {
                socket.close();
            } catch (IOException ignored) {}
        }
    }

    private Object customerLock(int customerID) {
        return m_customerLocks.computeIfAbsent(customerID, k -> new Object());
    }

    private IResourceManagerInternal rmForKey(String key) {
        if (key.startsWith("flight-")) return m_flightsRM;
        if (key.startsWith("car-")) return m_carsRM;
        if (key.startsWith("room-")) return m_roomsRM;
        throw new IllegalArgumentException("Unknown item key '" + key + "'");
    }

    // ==========================================
    // Forwarded Methods to Flights RM
    // ==========================================

    @Override
    public boolean addFlight(int flightNum, int flightSeats, int flightPrice) throws RemoteException {
        return m_flightsRM.addFlight(flightNum, flightSeats, flightPrice);
    }

    @Override
    public boolean deleteFlight(int flightNum) throws RemoteException {
        return m_flightsRM.deleteFlight(flightNum);
    }

    @Override
    public int queryFlight(int flightNum) throws RemoteException {
        return m_flightsRM.queryFlight(flightNum);
    }

    @Override
    public int queryFlightPrice(int flightNum) throws RemoteException {
        return m_flightsRM.queryFlightPrice(flightNum);
    }

    // ==========================================
    // Forwarded Methods to Cars RM
    // ==========================================

    @Override
    public boolean addCars(String location, int count, int price) throws RemoteException {
        return m_carsRM.addCars(location, count, price);
    }

    @Override
    public boolean deleteCars(String location) throws RemoteException {
        return m_carsRM.deleteCars(location);
    }

    @Override
    public int queryCars(String location) throws RemoteException {
        return m_carsRM.queryCars(location);
    }

    @Override
    public int queryCarsPrice(String location) throws RemoteException {
        return m_carsRM.queryCarsPrice(location);
    }

    // ==========================================
    // Forwarded Methods to Rooms RM
    // ==========================================

    @Override
    public boolean addRooms(String location, int count, int price) throws RemoteException {
        return m_roomsRM.addRooms(location, count, price);
    }

    @Override
    public boolean deleteRooms(String location) throws RemoteException {
        return m_roomsRM.deleteRooms(location);
    }

    @Override
    public int queryRooms(String location) throws RemoteException {
        return m_roomsRM.queryRooms(location);
    }

    @Override
    public int queryRoomsPrice(String location) throws RemoteException {
        return m_roomsRM.queryRoomsPrice(location);
    }

    // ==========================================
    // Customer Management (Local to Middleware)
    // ==========================================

    @Override
    public int newCustomer() throws RemoteException {
        return super.newCustomer();
    }

    @Override
    public boolean newCustomer(int customerID) throws RemoteException {
        synchronized (customerLock(customerID)) {
            return super.newCustomer(customerID);
        }
    }

    @Override
    public boolean deleteCustomer(int customerID) throws RemoteException {
        Trace.info("TCPMiddleware::deleteCustomer(" + customerID + ") called");
        synchronized (customerLock(customerID)) {
            Customer customer = (Customer) readData(Customer.getKey(customerID));
            if (customer == null) {
                Trace.warn("TCPMiddleware::deleteCustomer(" + customerID + ") failed--customer doesn't exist");
                return false;
            }

            // Return all reserved items to their respective backend ResourceManagers
            RMHashMap reservations = customer.getReservations();
            for (String reservedKey : reservations.keySet()) {
                ReservedItem reserveditem = customer.getReservedItem(reservedKey);
                String itemKey = reserveditem.getReservableItemKey();
                Trace.info("TCPMiddleware::deleteCustomer(" + customerID + ") unreserving " + itemKey + " x" + reserveditem.getCount());
                rmForKey(itemKey).unreserveResource(itemKey, reserveditem.getCount());
            }

            removeData(customer.getKey());
            Trace.info("TCPMiddleware::deleteCustomer(" + customerID + ") succeeded");
            return true;
        }
    }

    @Override
    public String queryCustomerInfo(int customerID) throws RemoteException {
        return super.queryCustomerInfo(customerID);
    }

    // ==========================================
    // Reservation Methods
    // ==========================================

    private boolean reserveItem(int customerID, IResourceManagerInternal rm, String key, String location) throws RemoteException {
        Trace.info("TCPMiddleware::reserveItem(customer=" + customerID + ", " + key + ", " + location + ") called");
        synchronized (customerLock(customerID)) {
            Customer customer = (Customer) readData(Customer.getKey(customerID));
            if (customer == null) {
                Trace.warn("TCPMiddleware::reserveItem(" + customerID + ", " + key + ") failed--customer doesn't exist");
                return false;
            }

            int price = rm.reserveResource(key);
            if (price < 0) {
                Trace.warn("TCPMiddleware::reserveItem(" + customerID + ", " + key + ") failed--item unavailable");
                return false;
            }

            customer.reserve(key, location, price);
            writeData(customer.getKey(), customer);
            Trace.info("TCPMiddleware::reserveItem(" + customerID + ", " + key + ") succeeded");
            return true;
        }
    }

    @Override
    public boolean reserveFlight(int customerID, int flightNum) throws RemoteException {
        return reserveItem(customerID, m_flightsRM, Flight.getKey(flightNum), String.valueOf(flightNum));
    }

    @Override
    public boolean reserveCar(int customerID, String location) throws RemoteException {
        return reserveItem(customerID, m_carsRM, Car.getKey(location), location);
    }

    @Override
    public boolean reserveRoom(int customerID, String location) throws RemoteException {
        return reserveItem(customerID, m_roomsRM, Room.getKey(location), location);
    }

    // ==========================================
    // Atomic Bundle Reservation (with Rollback)
    // ==========================================

    @Override
    public boolean bundle(int customerID, Vector<String> flightNumbers, String location, boolean car, boolean room) throws RemoteException {
        Trace.info("TCPMiddleware::bundle(" + customerID + ", flights=" + flightNumbers + ", location=" + location + ", car=" + car + ", room=" + room + ") called");
        synchronized (customerLock(customerID)) {
            Customer customer = (Customer) readData(Customer.getKey(customerID));
            if (customer == null) {
                Trace.warn("TCPMiddleware::bundle(" + customerID + ") failed--customer doesn't exist");
                return false;
            }

            List<IResourceManagerInternal> rms = new ArrayList<IResourceManagerInternal>();
            List<String> keys = new ArrayList<String>();
            List<String> locations = new ArrayList<String>();

            try {
                for (String flight : flightNumbers) {
                    int flightNum = Integer.parseInt(flight.trim());
                    rms.add(m_flightsRM);
                    keys.add(Flight.getKey(flightNum));
                    locations.add(String.valueOf(flightNum));
                }
            } catch (NumberFormatException e) {
                Trace.warn("TCPMiddleware::bundle(" + customerID + ") failed--invalid flight number");
                return false;
            }

            if (car) {
                rms.add(m_carsRM);
                keys.add(Car.getKey(location));
                locations.add(location);
            }
            if (room) {
                rms.add(m_roomsRM);
                keys.add(Room.getKey(location));
                locations.add(location);
            }

            int[] prices = new int[keys.size()];
            int taken = 0;
            boolean success = false;

            try {
                for (; taken < keys.size(); ++taken) {
                    prices[taken] = rms.get(taken).reserveResource(keys.get(taken));
                    if (prices[taken] < 0) {
                        Trace.warn("TCPMiddleware::bundle(" + customerID + ") failed--" + keys.get(taken) + " unavailable, rolling back");
                        return false;
                    }
                }
                success = true;
            } finally {
                // If any reservation failed midway, roll back all previously reserved items
                if (!success) {
                    for (int i = 0; i < taken; ++i) {
                        rms.get(i).unreserveResource(keys.get(i), 1);
                    }
                }
            }

            // All items successfully reserved: commit to customer's account
            for (int i = 0; i < keys.size(); ++i) {
                customer.reserve(keys.get(i), locations.get(i), prices[i]);
            }
            writeData(customer.getKey(), customer);
            Trace.info("TCPMiddleware::bundle(" + customerID + ") succeeded");
            return true;
        }
    }
}

package Server;

import Server.TCP.TCPMiddleware;
import Server.TCP.TCPResourceManager;
import Server.TCP.TCPResourceManagerProxy;

import java.util.Vector;

public class TestTCPPipeline {
    public static void main(String[] args) {
        System.out.println("==================================================");
        System.out.println("  STARTING END-TO-END TCP 3-TIER INTEGRATION TEST ");
        System.out.println("==================================================");

        try {
            // 1. Start Flights RM (Port 50001)
            Thread flightsThread = new Thread(() -> {
                TCPResourceManager rm = new TCPResourceManager("Flights", 50001);
                rm.start();
            });
            flightsThread.setDaemon(true);
            flightsThread.start();

            // 2. Start Cars RM (Port 50002)
            Thread carsThread = new Thread(() -> {
                TCPResourceManager rm = new TCPResourceManager("Cars", 50002);
                rm.start();
            });
            carsThread.setDaemon(true);
            carsThread.start();

            // 3. Start Rooms RM (Port 50003)
            Thread roomsThread = new Thread(() -> {
                TCPResourceManager rm = new TCPResourceManager("Rooms", 50003);
                rm.start();
            });
            roomsThread.setDaemon(true);
            roomsThread.start();

            Thread.sleep(600); // Wait for RMs to start

            // 4. Start Middleware (Port 50000)
            Thread mwThread = new Thread(() -> {
                TCPMiddleware mw = new TCPMiddleware("TCPMiddleware");
                mw.initConnections();
                mw.start();
            });
            mwThread.setDaemon(true);
            mwThread.start();

            Thread.sleep(600); // Wait for Middleware to start

            // 5. Connect Client Proxy to Middleware (Port 50000)
            System.out.println("\n--- Step 1: Connecting client to Middleware (localhost:50000) ---");
            TCPResourceManagerProxy client = new TCPResourceManagerProxy("localhost", 50000);
            System.out.println("Connected successfully!");

            // 6. Test Resource Addition
            System.out.println("\n--- Step 2: Adding Resources across 3 tiers ---");
            boolean fOk = client.addFlight(101, 10, 250);
            System.out.println("addFlight(101, 10, $250): " + (fOk ? "PASSED" : "FAILED"));

            boolean cOk = client.addCars("Montreal", 5, 40);
            System.out.println("addCars('Montreal', 5, $40): " + (cOk ? "PASSED" : "FAILED"));

            boolean rOk = client.addRooms("Montreal", 3, 100);
            System.out.println("addRooms('Montreal', 3, $100): " + (rOk ? "PASSED" : "FAILED"));

            // 7. Verify Queries
            System.out.println("\n--- Step 3: Verifying Queries ---");
            int flightSeats = client.queryFlight(101);
            System.out.println("queryFlight(101) = " + flightSeats + " (expected 10): " + (flightSeats == 10 ? "PASSED" : "FAILED"));

            int carCount = client.queryCars("Montreal");
            System.out.println("queryCars('Montreal') = " + carCount + " (expected 5): " + (carCount == 5 ? "PASSED" : "FAILED"));

            int roomCount = client.queryRooms("Montreal");
            System.out.println("queryRooms('Montreal') = " + roomCount + " (expected 3): " + (roomCount == 3 ? "PASSED" : "FAILED"));

            // 8. Test Customer & Direct Reservation
            System.out.println("\n--- Step 4: Customer Creation & Single Reservation ---");
            boolean custOk = client.newCustomer(1);
            System.out.println("newCustomer(1): " + (custOk ? "PASSED" : "FAILED"));

            boolean resFlightOk = client.reserveFlight(1, 101);
            System.out.println("reserveFlight(1, 101): " + (resFlightOk ? "PASSED" : "FAILED"));

            int remainingSeats = client.queryFlight(101);
            System.out.println("queryFlight(101) after reserve = " + remainingSeats + " (expected 9): " + (remainingSeats == 9 ? "PASSED" : "FAILED"));

            // 9. Test Bundle (All-or-Nothing)
            System.out.println("\n--- Step 5: Testing Bundle Reservation ---");
            Vector<String> flights = new Vector<String>();
            flights.add("101");
            boolean bundleOk = client.bundle(1, flights, "Montreal", true, true);
            System.out.println("bundle(1, [101], Montreal, car=true, room=true): " + (bundleOk ? "PASSED" : "FAILED"));

            System.out.println("queryFlight(101) after bundle = " + client.queryFlight(101) + " (expected 8)");
            System.out.println("queryCars('Montreal') after bundle = " + client.queryCars("Montreal") + " (expected 4)");
            System.out.println("queryRooms('Montreal') after bundle = " + client.queryRooms("Montreal") + " (expected 2)");

            // 10. Test Bundle Rollback on Failure
            System.out.println("\n--- Step 6: Testing Bundle Atomic Rollback on Failure ---");
            Vector<String> badFlights = new Vector<String>();
            badFlights.add("101");
            badFlights.add("999"); // 999 does not exist!
            boolean failedBundle = client.bundle(1, badFlights, "Montreal", false, false);
            System.out.println("bundle with non-existent flight 999 returned: " + failedBundle + " (expected false): " + (!failedBundle ? "PASSED" : "FAILED"));

            int seatsAfterFailedBundle = client.queryFlight(101);
            System.out.println("queryFlight(101) after failed bundle = " + seatsAfterFailedBundle + " (expected 8, verified rollback!): " + (seatsAfterFailedBundle == 8 ? "PASSED" : "FAILED"));

            // 11. Test deleteCustomer (Unreserving items)
            System.out.println("\n--- Step 7: Testing Customer Deletion & Item Release ---");
            boolean delCust = client.deleteCustomer(1);
            System.out.println("deleteCustomer(1): " + (delCust ? "PASSED" : "FAILED"));

            int restoredSeats = client.queryFlight(101);
            int restoredCars = client.queryCars("Montreal");
            int restoredRooms = client.queryRooms("Montreal");

            System.out.println("Seats restored = " + restoredSeats + " (expected 10): " + (restoredSeats == 10 ? "PASSED" : "FAILED"));
            System.out.println("Cars restored = " + restoredCars + " (expected 5): " + (restoredCars == 5 ? "PASSED" : "FAILED"));
            System.out.println("Rooms restored = " + restoredRooms + " (expected 3): " + (restoredRooms == 3 ? "PASSED" : "FAILED"));

            // 12. Test Concurrent Clients
            System.out.println("\n--- Step 8: Testing Concurrent Clients ---");
            int numThreads = 5;
            Thread[] threads = new Thread[numThreads];
            boolean[] threadResults = new boolean[numThreads];

            for (int i = 0; i < numThreads; i++) {
                final int idx = i;
                threads[i] = new Thread(() -> {
                    try {
                        TCPResourceManagerProxy c = new TCPResourceManagerProxy("localhost", 50000);
                        int cid = 100 + idx;
                        c.newCustomer(cid);
                        boolean r = c.reserveFlight(cid, 101);
                        threadResults[idx] = r;
                        c.close();
                    } catch (Exception e) {
                        e.printStackTrace();
                        threadResults[idx] = false;
                    }
                });
                threads[i].start();
            }

            for (int i = 0; i < numThreads; i++) {
                threads[i].join();
            }

            boolean allPassed = true;
            for (int i = 0; i < numThreads; i++) {
                if (!threadResults[i]) allPassed = false;
            }
            System.out.println("5 concurrent clients reserving seats: " + (allPassed ? "PASSED" : "FAILED"));
            System.out.println("Remaining seats = " + client.queryFlight(101) + " (expected 5): " + (client.queryFlight(101) == 5 ? "PASSED" : "FAILED"));

            client.close();
            System.out.println("\n==================================================");
            System.out.println("  >>> ALL TCP END-TO-END TESTS PASSED 100%! <<<");
            System.out.println("==================================================");

        } catch (Exception e) {
            System.err.println("Test failed with exception:");
            e.printStackTrace();
        }
    }
}

